var Engine = Packages.com.twinsoft.convertigo.engine.Engine;

function parseOptionBoolean(value, defaultValue) {
  if (value === null || typeof value === "undefined") {
    return defaultValue;
  }
  var text = String(value).trim();
  if (!text.length) {
    return defaultValue;
  }
  text = text.toLowerCase();
  if (text === "true" || text === "1" || text === "yes" || text === "on") {
    return true;
  }
  if (text === "false" || text === "0" || text === "no" || text === "off") {
    return false;
  }
  return defaultValue;
}

var targetRaw = target == null ? "" : String(target).trim();
var includeBuiltInFlag = parseOptionBoolean(includeBuiltIn, true);
var includeSharedFlag = parseOptionBoolean(includeShared, true);

var filterRaw = filter == null ? "" : String(filter);
var filterText = filterRaw.trim();
var hasFilter = filterText.length > 0;
if (hasFilter) {
  filterText = filterText.toLowerCase();
}

var limitRaw = limit == null ? "" : String(limit).trim();
var limitValue = 0;
if (limitRaw.length > 0) {
  try {
    limitValue = parseInt(limitRaw, 10);
    if (isNaN(limitValue) || !isFinite(limitValue) || limitValue < 0) {
      limitValue = 0;
    }
  } catch (_ignoreLimit) {
    limitValue = 0;
  }
}

var cursorRaw = "";
if (typeof _nextCursor !== "undefined" && _nextCursor !== null) {
  var cursorText = String(_nextCursor).trim();
  if (cursorText.length && cursorText.toLowerCase() !== "undefined" && cursorText.indexOf("org.mozilla.javascript.Undefined") !== 0) {
    cursorRaw = cursorText;
  }
}

var startIndexValue = 0;
if (cursorRaw.length > 0) {
  try {
    var parsedCursor = parseInt(cursorRaw, 10);
    if (!isNaN(parsedCursor) && parsedCursor >= 0) {
      startIndexValue = parsedCursor;
    }
  } catch (_ignoredCursor) {}
}
if (limitValue <= 0) {
  cursorRaw = "";
  startIndexValue = 0;
}

var parentDbo = null;
var folderTypeValue = "";
if (targetRaw.length > 0) {
  var candidates = [];
  candidates.push(targetRaw);
  var lower = targetRaw.toLowerCase();
  if (lower !== targetRaw) {
    candidates.push(lower);
  }
  var colonIndex = targetRaw.indexOf(":");
  if (colonIndex !== -1) {
    var leftPart = targetRaw.substring(0, colonIndex);
    var namePart = targetRaw.substring(colonIndex + 1);
    var dotIndex = leftPart.lastIndexOf(".");
    if (dotIndex !== -1) {
      var base = leftPart.substring(0, dotIndex);
      var suffix = namePart;
      var suffixLower = namePart.toLowerCase();
      candidates.push(leftPart + ":" + suffixLower);
      candidates.push(base + "." + suffix);
      if (suffixLower !== suffix) {
        candidates.push(base + "." + suffixLower);
      }
    }
  }
  for (var i = 0; i < candidates.length; i++) {
    try {
      parentDbo = Engine.theApp.databaseObjectsManager.getDatabaseObjectByQName(candidates[i]);
      if (parentDbo != null) {
        break;
      }
    } catch (_ignoredCandidate) {}
  }
}

var parentQNameValue = parentDbo != null ? String(parentDbo.getQName()) : "";
var parentClassNameValue = parentDbo != null ? parentDbo.getClass().getName() : "";

paletteCategories = [];
paletteParent = parentDbo;
paletteFolderType = null;
paletteIncludeBuiltIn = includeBuiltInFlag === true;
paletteIncludeShared = includeSharedFlag === true;
paletteFilterInfo = {
  hasFilter: hasFilter,
  text: filterText,
  raw: filterRaw
};
paletteLimit = limitValue > 0 ? limitValue : 0;
paletteStartIndex = startIndexValue;
paletteNextCursor = "";
paletteHasMore = false;
paletteTotalMatches = 0;
paletteCursorInput = cursorRaw;
paletteItemCount = 0;

resultInfo = {
  target: targetRaw,
  parentQName: parentQNameValue,
  parentClass: parentClassNameValue,
  folderType: folderTypeValue,
  includeBuiltIn: paletteIncludeBuiltIn,
  includeShared: paletteIncludeShared,
  filter: hasFilter ? filterRaw : "",
  limit: paletteLimit > 0 ? paletteLimit : null,
  startIndex: startIndexValue,
  cursorInput: cursorRaw,
  categories: 0,
  returned: 0,
  truncated: false,
  hasMore: false,
  nextCursor: "",
  totalMatches: 0
};

var loadResult = C8O.palette.listEntries({
  parentDbo: paletteParent,
  folderType: paletteFolderType,
  includeBuiltIn: paletteIncludeBuiltIn === true,
  includeShared: paletteIncludeShared === true,
  filterInfo: paletteFilterInfo || { hasFilter: false, text: "" },
  limit: paletteLimit > 0 ? paletteLimit : 0,
  startIndex: paletteStartIndex > 0 ? paletteStartIndex : 0
});

paletteCategories = loadResult && loadResult.categories ? loadResult.categories : [];
paletteItemCount = loadResult && loadResult.returned ? Number(loadResult.returned) : 0;
paletteTotalMatches = loadResult && loadResult.totalMatches ? Number(loadResult.totalMatches) : 0;
paletteHasMore = loadResult && loadResult.hasMore === true;
paletteNextCursor = paletteHasMore ? String(loadResult.nextCursor || ((paletteStartIndex || 0) + paletteItemCount)) : "";

resultInfo.categories = paletteCategories.length;
resultInfo.returned = paletteItemCount;
resultInfo.totalMatches = paletteTotalMatches;
resultInfo.nextCursor = paletteNextCursor;
resultInfo.hasMore = paletteHasMore;

