resultInfo.categories = paletteCategories.length;
resultInfo.returned = paletteItemCount;
resultInfo.limit = paletteLimit > 0 ? paletteLimit : null;
resultInfo.startIndex = paletteStartIndex || 0;
resultInfo.cursorInput = paletteCursorInput || "";
resultInfo.hasMore = paletteHasMore === true;
if (paletteItemCount <= 0) { resultInfo.hasMore = false; paletteHasMore = false; paletteNextCursor = ""; }
resultInfo.nextCursor = resultInfo.hasMore ? (paletteNextCursor || String((paletteStartIndex || 0) + paletteItemCount)) : "";
resultInfo.truncated = resultInfo.hasMore;
resultInfo.totalMatches = paletteTotalMatches || (paletteStartIndex || 0) + paletteItemCount;

if (paletteCategories && C8O && C8O.palette && typeof C8O.palette.computeListEntryCounts === "function") {
  for (var i = 0; i < paletteCategories.length; i++) {
    var category = paletteCategories[i];
    if (!category || !category.items) {
      continue;
    }
    for (var j = 0; j < category.items.length; j++) {
      var entry = category.items[j];
      if (!entry || !entry.className) {
        continue;
      }
      var counts = C8O.palette.computeListEntryCounts(entry.className);
      if (counts) {
        entry.propertyCount = counts.propertyCount || 0;
      }
    }
  }
}

if (paletteCategories) {
  for (var i = 0; i < paletteCategories.length; i++) {
    var category = paletteCategories[i];
    if (!category || !category.items) {
      continue;
    }
    for (var j = 0; j < category.items.length; j++) {
      var entry = category.items[j];
      if (!entry) {
        continue;
      }
      if (entry.describe) {
        delete entry.describe;
      }
    }
  }
}

function sortInsensitive(a, b) {
  var an = (a.name || "").toLowerCase();
  var bn = (b.name || "").toLowerCase();
  if (an < bn) { return -1; }
  if (an > bn) { return 1; }
  return 0;
}

paletteCategories = paletteCategories.filter(function(cat) {
  return cat.items && cat.items.length;
});

for (var i = 0; i < paletteCategories.length; i++) {
  var cat = paletteCategories[i];
  cat.items.sort(sortInsensitive);
}

paletteCategories.sort(sortInsensitive);
